import {controller, target} from '@github/catalyst'
import {requestSubmit} from '@github-ui/form-utils'
import invariant from 'tiny-invariant'

@controller('dependabot-settings-toggle')
export class DependabotSettingsToggleElement extends HTMLElement {
  @target declare settingForm: HTMLFormElement
  @target declare settingInput: HTMLInputElement
  @target declare settingsToggleSwitch: HTMLElement

  toggleSetting() {
    if (!this.settingForm || !this.settingsToggleSwitch || !this.settingInput) return

    // Query for the inner toggle button that Primer manages
    const toggleButton = this.settingsToggleSwitch.querySelector<HTMLButtonElement>(
      "button[data-target='toggle-switch.switch']",
    )
    invariant(toggleButton, 'inner toggle button must exist')

    // Read the current state from aria-pressed (note: Primer uses aria-pressed, not aria-checked)
    const isEnabled = toggleButton.getAttribute('aria-pressed') === 'true'
    this.settingInput.value = isEnabled ? 'enabled' : 'disabled'

    // Submit the form
    requestSubmit(this.settingForm)
  }
}
